    /**
     * @dev Multiply an elliptic curve point by a 2 power base (i.e., (2^exp)*P)).
     */
    function multiplyPowerBase2(
        uint x0,
        uint y0,
        uint exp
    ) internal  returns (uint, uint) {
        uint base2X = x0;
        uint base2Y = y0;
